def transform_fill_twos(grid):
    """
    Based on demo pattern: if row has 3s, fill from after first 3 to end
    Also fill before the 3s if there's a marker at edge
    Convert 1s to 4s
    """
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        threes = [c for c in range(w) if result[r][c] == 3]
        ones = [c for c in range(w) if result[r][c] == 1]

        if on and thre:
            # This row should fill between first 3 and last 3
            if len(threes) >= 2:
                first3 = threes[0]
                last3 = threes[-1]

                # Convert special 1s to 4s
                for c in ones:
                    result[r][c] = 4

                # Fill between first and last 3
                for c in range(first3 + 1, last3):
                    if result[r][c] == 9:
                        result[r][c] = 1

            # Fill from marker edge
            if result[r][0] != 9:
                for c in range(1, w):
                    if result[r][c] == 9:
                        result[r][c] = 1
                    elif result[r][c] == 1:
                        result[r][c] = 4
            elif result[r][w-1] != 9:
                for c in range(w-2, 0, -1):
                    if result[r][c] == 9:
                        result[r][c] = 1
                    elif result[r][c] == 1:
                        result[r][c] = 4

    return result

